import assert from "node:assert/strict";
const total = (price, quantity) => price * quantity;
test("calculates a cart line", () => {
  assert.equal(total(199, 2), 398);
});
test("keeps zero quantity deterministic", () => {
  assert.equal(total(199, 0), 0);
});

